const keyA = new Uint8Array(32).fill(1), keyB = new Uint8Array(32).fill(2);
let cur = keyA;
const c = new Contract({ secretKey: (ctx) => [ctx.privateState, cur] });
const addrA = pureCircuits.publicKey(keyA), addrB = pureCircuits.publicKey(keyB);
const coin = '0'.repeat(64);
cur = keyA;
let st = c.initialState(rt.createConstructorContext({}, coin));
let ctx = rt.createCircuitContext(rt.dummyContractAddress(), coin, st.currentContractState.data, st.currentPrivateState);
